hooks.command:
python3 -I -c 'import os
os.umask(0o077)
try:
    try:
        os.mkdir("/tmp/codex", 0o700)
    except FileExistsError:
        pass
    fd = os.open("/tmp/codex", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        if os.fstat(fd).st_uid != os.geteuid():
            raise PermissionError
        os.fchmod(fd, 0o700)
    finally:
        os.close(fd)
except OSError:
    raise SystemExit(1)
' || printf '%s\n' '{"continue":false,"stopReason":"/tmp/codex を安全に準備できませんでした。所有者と種類を確認してください。"}'
